    "statement": "select flag, sum(sessions) as sessions from ( select arrayJoin(array( if(bitAnd(flags, 1)= 1, 'Asymmetric', ''), if(bitAnd(flags, 2)= 2, 'Bulky', ''), if(bitAnd(flags, 4)= 4, 'CBR Streaming', ''), if(bitAnd(flags, 8)= 8, 'Client is Local', ''), if(bitAnd(flags, 16)= 16, 'Server is Local', ''), if(bitAnd(flags, 32)= 32, 'Download', ''), if(bitAnd(flags, 64)= 64, 'Interactive', ''), if(bitAnd(flags, 128)= 128, 'Inbound', ''), if(bitAnd(flags, 256)= 256, 'Outbound', ''), if(bitAnd(flags, 512)= 512, 'Pseudo Unidirectional', ''), if(bitAnd(flags, 1024)= 1024, 'Streaming', ''), if(bitAnd(flags, 2048)= 2048, 'Unidirectional', ''), if(bitAnd(flags, 4096)= 4096, 'Random looking', ''), if(bitAnd(flags, 8192)= 8192, 'C2S', ''), if(bitAnd(flags, 16384)= 16384, 'S2C', ''), if(bitAnd(flags, 32768)= 32768, 'Bidirectional', ''), if(flags=0, 'N/A', '') )) as flag , bytes, packets, sessions from ( select flags, count(*) as sessions, sum(sent_bytes + received_bytes) as bytes, sum(sent_pkts + received_pkts) as packets from session_record as sr where recv_time >= UNIX_TIMESTAMP('{{start_time}}') and recv_time <UNIX_TIMESTAMP('{{end_time}}') group by flags ) ) where notEmpty(flag) group by flag order by sessions desc",
    "exec_mode": "oneshot"
}

